def process_payment(idempotency_key, amount):
    import json
    import time

    cache_key = f"idemp:{idempotency_key}"
    pending_marker = "__IDEMPOTENCY_PENDING__"
    deadline = time.monotonic() + 120

    while True:
        claimed = redis.set(cache_key, pending_marker, nx=True, ex=120)
        if claimed:
            receipt = stripe.Charge.create(amount=amount)
            redis.set(cache_key, json.dumps(receipt), ex=120)
            return receipt

        cached = redis.get(cache_key)
        if cached is None:
            continue
        if isinstance(cached, bytes):
            cached = cached.decode("utf-8")
        if cached != pending_marker:
            return json.loads(cached)
        if time.monotonic() >= deadline:
            raise TimeoutError("Timed out waiting for the cached payment receipt")
        time.sleep(0.01)

